args.TargetContent:
fetch("/api/generate-async", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ recordId: record.id, payload }),
})
  .then(async (res) => {
    if (!res.ok) {
      const errData = await res.json().catch(() => null);
      throw new Error(errData?.error || `Falha na API (status ${res.status})`);
    }
    return res.json();
  })
  .then(async (data) => {
    console.log("✅ Geracao concluida, salvando no Supabase...");
    if (data?.success && data?.variations) {
      const sb = createClient();
      const { error } = await sb
        .from("generated_scripts")
        .update({
          status: "completed",
          cards_data: data.variations,
          completed_at: new Date().toISOString(),
        })
        .eq("id", record.id);
      if (error) {
        console.error("❌ Erro ao salvar no Supabase:", error);
      } else {
        console.log("✅ Registro atualizado no Supabase");
      }
      if (pollRef.current) {
        clearInterval(pollRef.current);
        pollRef.current = null;
      }
      setActiveGeneration(null);
      load();
    }
  })
  .catch((err) => {
    console.error("❌ Erro ao disparar geracao async:", err);
    const msg =
      err.name === "AbortError"
        ? "A IA demorou muito para responder."
        : err.message || "Erro ao conectar com a IA.";
    const sb = createClient();
    sb.from("generated_scripts")
      .update({ status: "error", error_message: msg })
      .eq("id", record.id)
      .then(({ error }) => {
        if (error) console.error("Erro ao marcar registro como error:", error);
      });
  });

