function parseJsonResponse(content) {
  if (!content) return null;

  let cleanContent = content
    .replace(/```json\s*/gi, "")
    .replace(/```\s*/g, "")
    .replace(/^[\s\S]*?\[/, "[")
    .replace(/\][\s\S]*?$/, "]")
    .trim();

  if (cleanContent.startsWith('"') && cleanContent.endsWith('"')) {
    try { cleanContent = JSON.parse(cleanContent); } catch {}
  }

  let jsonMatch = cleanContent.match(/\[[\s\S]*\]/);
  if (!jsonMatch) {
    const objMatch = cleanContent.match(/\{[\s\S]*\}/);
    if (objMatch) jsonMatch = [objMatch[0]];
  }
  if (!jsonMatch) return null;

  // Try direct parse
  try {
    const parsed = JSON.parse(jsonMatch[0]);
    if (Array.isArray(parsed) && parsed.length > 0) return parsed;
  } catch (e) {
    console.log('Direct parse catch:', e.message);
  }

  // Try fixing truncated JSON: add missing closing brackets
  let fixed = jsonMatch[0]
    .replace(/\\n/g, " ")
    .replace(/\\t/g, " ")
    .replace(/\\r/g, "")
    .replace(/[\r\n]+/g, " ")
    .replace(/\t/g, " ")
    .replace(/,\s*([\]}])/g, "$1")
    .replace(/'/g, '"')
    .replace(/\\+"/g, '"')
    .replace(/  +/g, " ")
    .trim();

  // Count open/close brackets to fix truncated JSON
  let openBrackets = 0, openBraces = 0, inString = false;
  for (const ch of fixed) {
    if (ch === '"' && !inString) { inString = true; continue; }
    if (ch === '"' && inString) { inString = false; continue; }
    if (!inString) {
      if (ch === '[') openBrackets++;
      if (ch === ']') openBrackets--;
      if (ch === '{') openBraces++;
      if (ch === '}') openBraces--;
    }
  }
  // If truncated, close what's open
  if (openBrackets > 0 || openBraces > 0) {
    fixed = fixed.replace(/,\s*$/, "");
    while (openBraces > 0) { fixed += "}"; openBraces--; }
    while (openBrackets > 0) { fixed += "]"; openBrackets--; }
  }

  try {
    const parsed = JSON.parse(fixed);
    if (Array.isArray(parsed) && parsed.length > 0) return parsed;
  } catch (e) {
    console.log('Fixed parse catch:', e.message);
  }

  // Last resort: extract individual objects with nested bracket support
  const objects = [];
  let depth = 0, start = -1;
  for (let i = 0; i < fixed.length; i++) {
    if (fixed[i] === '{') {
      if (depth === 0) start = i;
      depth++;
    } else if (fixed[i] === '}') {
      depth--;
      if (depth === 0 && start >= 0) {
        try {
          const cleaned = fixed.slice(start, i + 1).replace(/,\s*([}\]])/g, "$1");
          const obj = JSON.parse(cleaned);
          if (obj && typeof obj === "object" && !Array.isArray(obj)) {
            objects.push(obj);
          }
        } catch (e) {
          console.log('Object parse catch:', e.message);
        }
        start = -1;
      }
    }
  }
  return objects.length > 0 ? objects : null;
}

