// ─── Smart Cuts (Cortar Silêncios / Transcrição) ───────────────────

// Detect silences in audio via Web Audio API (Offline)
const handleAnalyzeSilence = async () => {
  if (!videoFile) return;
  setIsAnalyzing(true);
  setAnalysisResult(null);
  setError(null);

  try {
    const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
    const arrayBuffer = await videoFile.arrayBuffer();
    const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);

    const sampleRate = audioBuffer.sampleRate;
    const channelData = audioBuffer.getChannelData(0); // single channel
    const numSamples = channelData.length;

    // 50ms block size
    const blockSize = Math.round(sampleRate * 0.05);
    const totalBlocks = Math.floor(numSamples / blockSize);

    // Convert dB threshold to linear amplitude
    const linearThreshold = Math.pow(10, silenceThreshold / 20);

    const blocks: { time: number; rms: number; isSilence: boolean }[] = [];
    for (let i = 0; i < totalBlocks; i++) {
      const startSample = i * blockSize;
      let sum = 0;
      for (let j = 0; j < blockSize; j++) {
        const val = channelData[startSample + j];
        sum += val * val;
      }
      const rms = Math.sqrt(sum / blockSize);
      blocks.push({
        time: i * 0.05,
        rms,
        isSilence: rms < linearThreshold,
      });
    }

    // Group silences
    const silences: { start: number; end: number; duration: number }[] = [];
    let inSilence = false;
    let silenceStart = 0;

    for (let i = 0; i < blocks.length; i++) {
      const block = blocks[i];
      if (block.isSilence) {
        if (!inSilence) {
          inSilence = true;
          silenceStart = block.time;
        }
      } else {
        if (inSilence) {
          inSilence = false;
          const duration = block.time - silenceStart;
          if (duration >= minSilenceDuration) {
            silences.push({ start: silenceStart, end: block.time, duration });
          }
        }
      }
    }
    if (inSilence) {
      const duration = (blocks.length * 0.05) - silenceStart;
      if (duration >= minSilenceDuration) {
        silences.push({ start: silenceStart, end: blocks.length * 0.05, duration });
      }
    }

    // Calculate keep intervals with margins
    const totalDuration = numSamples / sampleRate;
    const keeps: { start: number; end: number }[] = [];
    let currentStart = 0;

    for (const silence of silences) {
      const keepStart = currentStart;
      const keepEnd = Math.max(currentStart, silence.start - paddingMargin);

      if (keepEnd > keepStart + 0.1) {
        keeps.push({ start: keepStart, end: keepEnd });
      }
      currentStart = Math.min(totalDuration, silence.end + paddingMargin);
    }

    if (totalDuration > currentStart + 0.1) {
      keeps.push({ start: currentStart, end: totalDuration });
    }

    const reducedDuration = keeps.reduce((sum, k) => sum + (k.end - k.start), 0);

    setAnalysisResult({
      silences,
      keeps,
      totalDuration,
      reducedDuration,
    });
  } catch (err: any) {
    console.error("Erro ao analisar silêncio:", err);
    setError("Não foi possível decodificar o áudio do vídeo para análise.");
  } finally {
    setIsAnalyzing(false);
  }
};

// Trim and merge video based on keep segments using FFmpeg.wasm
const handleApplySilenceCuts = async () => {
  if (!videoFile || !analysisResult || analysisResult.keeps.length === 0) return;
  setIsApplyingCuts(true);
  setCutProgress(0);
  setError(null);

  try {
    const ffmpeg = await initFFmpeg((progress) => setCutProgress(progress));
    await ffmpeg.writeFile("input.mp4", await fetchFile(videoFile));

    const keeps = analysisResult.keeps;
    let filterComplex = "";
    let concatInputs = "";

    keeps.forEach((keep, idx) => {
      filterComplex += `[0:v]trim=start=${keep.start.toFixed(3)}:end=${keep.end.toFixed(3)},setpts=PTS-STARTPTS[v${idx}]; `;
      filterComplex += `[0:a]atrim=start=${keep.start.toFixed(3)}:end=${keep.end.toFixed(3)},asetpts=PTS-STARTPTS[a${idx}]; `;
      concatInputs += `[v${idx}][a${idx}]`;
    });
    filterComplex += `${concatInputs}concat=n=${keeps.length}:v=1:a=1[outv][outa]`;

    await ffmpeg.exec([
      "-i",
      "input.mp4",
      "-filter_complex",
      filterComplex,
      "-map",
      "[outv]",
      "-map",
      "[outa]",
      "-c:v",
      "libx264",
      "-preset",
      "ultrafast",
      "-c:a",
      "aac",
      "output.mp4",
    ]);

    const outputData = await ffmpeg.readFile("output.mp4");
    const trimmedFile = new File([outputData], videoFile.name, { type: "video/mp4" });

    if (!originalFile) {
      setOriginalFile(videoFile);
    }
    setVideoFile(trimmedFile);
    setAnalysisResult(null);
  } catch (err: any) {
    console.error("Erro ao aplicar cortes:", err);
    setError("Falha ao cortar o vídeo usando o FFmpeg.wasm.");
  } finally {
    setIsApplyingCuts(false);
  }
};

// Undo cuts and restore original video
const handleUndoCuts = () => {
  if (originalFile) {
    setVideoFile(originalFile);
    setOriginalFile(null);
    setAnalysisResult(null);
    setTranscriptionSegments([]);
  }
};

// Speech-to-text Transcription using Groq Whisper API
const handleTranscribeGroq = async () => {
  if (!videoFile) return;
  if (!groqKey.trim()) {
    alert("Por favor, insira sua Groq API Key nas configurações ou no painel.");
    return;
  }
  setIsTranscribing(true);
  setError(null);

  try {
    // Save key
    localStorage.setItem("groq_api_key", groqKey);

    const ffmpeg = await initFFmpeg();
    await ffmpeg.writeFile("input.mp4", await fetchFile(videoFile));

    // Extract audio only in MP3 to save bandwidth and fit Groq limit
    await ffmpeg.exec([
      "-i",
      "input.mp4",
      "-vn",
      "-c:a",
      "libmp3lame",
      "-b:a",
      "128k",
      "audio.mp3",
    ]);

    const audioData = await ffmpeg.readFile("audio.mp3");
    const audioBlob = new Blob([audioData], { type: "audio/mp3" });

    const formData = new FormData();
    formData.append("file", audioBlob, "audio.mp3");
    formData.append("model", "whisper-large-v3");
    formData.append("response_format", "verbose_json");

    const response = await fetch("https://api.groq.com/openai/v1/audio/transcriptions", {
      method: "POST",
      headers: {
        "Authorization": `Bearer ${groqKey}`,
      },
      body: formData,
    });

    if (!response.ok) {
      const errData = await response.json().catch(() => null);
      throw new Error(errData?.error?.message || `Erro HTTP ${response.status}`);
    }

    const data = await response.json();
    const segments = (data.segments || []).map((seg: any, idx: number) => ({
      id: idx,
      start: seg.start,
      end: seg.end,
      text: seg.text,
      enabled: true,
    }));

    setTranscriptionSegments(segments);
  } catch (err: any) {
    console.error("Erro na transcrição:", err);
    setError("Falha ao transcrever o áudio com a API do Groq: " + err.message);
  } finally {
    setIsTranscribing(false);
  }
};

// Trim and merge video based on transcription keeps
const handleApplyTextCuts = async () => {
  if (!videoFile || transcriptionSegments.length === 0) return;
  const keeps = transcriptionSegments.filter((seg) => seg.enabled);
  if (keeps.length === 0) {
    alert("Selecione pelo menos uma frase para manter no vídeo final!");
    return;
  }
  setIsApplyingCuts(true);
  setCutProgress(0);
  setError(null);

  try {
    const ffmpeg = await initFFmpeg((progress) => setCutProgress(progress));
    await ffmpeg.writeFile("input.mp4", await fetchFile(videoFile));

    let filterComplex = "";
    let concatInputs = "";

    keeps.forEach((keep, idx) => {
      filterComplex += `[0:v]trim=start=${keep.start.toFixed(3)}:end=${keep.end.toFixed(3)},setpts=PTS-STARTPTS[v${idx}]; `;
      filterComplex += `[0:a]atrim=start=${keep.start.toFixed(3)}:end=${keep.end.toFixed(3)},asetpts=PTS-STARTPTS[a${idx}]; `;
      concatInputs += `[v${idx}][a${idx}]`;
    });
    filterComplex += `${concatInputs}concat=n=${keeps.length}:v=1:a=1[outv][outa]`;

    await ffmpeg.exec([
      "-i",
      "input.mp4",
      "-filter_complex",
      filterComplex,
      "-map",
      "-map",
      "[outv]",
      "[outa]",
      "-c:v",
      "libx264",
      "-preset",
      "ultrafast",
      "-c:a",
      "aac",
      "output.mp4",
    ]);

    const outputData = await ffmpeg.readFile("output.mp4");
    const trimmedFile = new File([outputData], videoFile.name, { type: "video/mp4" });

    if (!originalFile) {
      setOriginalFile(videoFile);
    }
    setVideoFile(trimmedFile);
    setTranscriptionSegments([]);
  } catch (err: any) {
    console.error("Erro ao aplicar cortes de texto:", err);
    setError("Falha ao processar o vídeo com FFmpeg.");
  } finally {
    setIsApplyingCuts(false);
  }
};

