// Render styled text on a transparent Canvas and return it as a PNG blob
const generateTextOverlayBlob = (text: string, size: number, color: string, textY: number): Promise<Blob> => {
  return new Promise((resolve, reject) => {
    const canvas = document.createElement("canvas");
    canvas.width = 1920;
    canvas.height = 1080;
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      reject(new Error("Não foi possível inicializar o contexto 2D do Canvas"));
      return;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.font = `bold ${size * 2.2}px Inter, system-ui, -apple-system, BlinkMacSystemFont, sans-serif`;
    ctx.fillStyle = color;
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";

    ctx.strokeStyle = "#000000";
    ctx.lineWidth = size * 0.45;
    ctx.lineJoin = "round";

    ctx.shadowColor = "rgba(0, 0, 0, 0.6)";
    ctx.shadowBlur = 14;
    ctx.shadowOffsetX = 4;
    ctx.shadowOffsetY = 4;

    const lines = text.split("\n");
    const lineHeight = size * 2.6;
    const targetY = (canvas.height * textY) / 100;

    lines.forEach((line, index) => {
      const y = targetY + ((index - (lines.length - 1) / 2) * lineHeight);
      ctx.strokeText(line, canvas.width / 2, y);
      ctx.fillText(line, canvas.width / 2, y);
    });

    canvas.toBlob((blob) => {
      if (blob) {
        resolve(blob);
      } else {
        reject(new Error("Falha ao exportar imagem do canvas"));
      }
    }, "image/png");
  });
};

// Compile color settings, watermark logo, and text overlay via FFmpeg.wasm
const handleApplyVisualEffects = async () => {
  if (!videoFile) return;
  setIsApplyingEffects(true);
  setCutProgress(0);
  setError(null);

  try {
    const ffmpeg = await initFFmpeg((progress) => setCutProgress(progress));
    await ffmpeg.writeFile("input.mp4", await fetchFile(videoFile));

    const inputFiles: string[] = ["input.mp4"];
    let filterComplex = "";
    let lastOutput = "0:v";

    // 1. Color Adjustment (eq filter)
    let eqFilter = "";
    if (brightness !== 0.0 || contrast !== 1.0) {
      eqFilter = `eq=brightness=${brightness.toFixed(2)}:contrast=${contrast.toFixed(2)}`;
    }

    // If we have eq filter, apply it
    if (eqFilter) {
      filterComplex += `[0:v]${eqFilter}[vcolor]; `;
      lastOutput = "vcolor";
    }

    // 2. Logo Overlay
    if (logoFile) {
      await ffmpeg.writeFile("logo.png", await fetchFile(logoFile));
      inputFiles.push("logo.png");
      const logoInputIdx = inputFiles.length - 1;

      let logoX = "20";
      let logoY = "20";
      if (logoPosition === "top-right") {
        logoX = "main_w-overlay_w-20";
      } else if (logoPosition === "bottom-left") {
        logoY = "main_h-overlay_h-20";
      } else if (logoPosition === "bottom-right") {
        logoX = "main_w-overlay_w-20";
        logoY = "main_h-overlay_h-20";
      }

      filterComplex += `[${logoInputIdx}:v]scale=${logoSize}:-1[logo]; `;
      filterComplex += `[${lastOutput}][logo]overlay=x=${logoX}:y=${logoY}[vlogo]; `;
      lastOutput = "vlogo";
    }

    // 3. Text Overlay
    if (overlayText.trim()) {
      const textBlob = await generateTextOverlayBlob(
        overlayText,
        overlayTextSize,
        overlayTextColor,
        overlayTextY
      );
      const textFile = new File([textBlob], "text_overlay.png", { type: "image/png" });
      await ffmpeg.writeFile("text.png", await fetchFile(textFile));
      inputFiles.push("text.png");
      const textInputIdx = inputFiles.length - 1;

      filterComplex += `[${lastOutput}][${textInputIdx}:v]overlay=0:0[vfinal]; `;
      lastOutput = "vfinal";
    }

    const args: string[] = [];
    inputFiles.forEach((file) => {
      args.push("-i", file);
    });

    if (filterComplex) {
      // Strip trailing semicolon and space
      filterComplex = filterComplex.trim().replace(/;$/, "");
      args.push("-filter_complex", filterComplex);
      args.push("-map", `[${lastOutput}]`);
      args.push("-map", "0:a"); // preserve audio
    }

    args.push("-c:v", "libx264", "-preset", "ultrafast", "-c:a", "aac", "output.mp4");

    await ffmpeg.exec(args);

    const outputData = await ffmpeg.readFile("output.mp4");
    const processedFile = new File([outputData as any], videoFile.name, { type: "video/mp4" });

    if (!originalFile) {
      setOriginalFile(videoFile);
    }
    setVideoFile(processedFile);

    // Clean up inputs in state
    setOverlayText("");
    setLogoFile(null);
  } catch (err: any) {
    console.error("Erro ao aplicar efeitos visuais:", err);
    setError("Falha ao renderizar os efeitos visuais usando FFmpeg.wasm.");
  } finally {
    setIsApplyingEffects(false);
  }
};

