}, [videoFile]);

// Filmstrip/Frame Extraction Effect
useEffect(() => {
  if (!videoFile) {
    setTimelineFrames([]);
    return;
  }

  const extractFrames = async () => {
    setIsExtractingFrames(true);
    const frames: string[] = [];
    const video = document.createElement("video");
    video.src = URL.createObjectURL(videoFile);
    video.preload = "auto";
    video.muted = true;
    video.playsInline = true;

    await new Promise((resolve) => {
      video.onloadedmetadata = resolve;
    });

    const duration = video.duration;
    const steps = 10; // Number of frames to extract
    const stepDuration = duration / steps;
    const canvas = document.createElement("canvas");
    canvas.width = 160;
    canvas.height = 90;
    const ctx = canvas.getContext("2d");

    for (let i = 0; i < steps; i++) {
      const time = i * stepDuration + 0.1; // avoid exact start frame which might be black
      video.currentTime = time;

      await new Promise((resolve) => {
        const onSeeked = () => {
          video.removeEventListener("seeked", onSeeked);
          if (ctx) {
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
            frames.push(canvas.toDataURL("image/jpeg", 0.7));
          }
          resolve(null);
        };
        video.addEventListener("seeked", onSeeked);
      });
    }

    setTimelineFrames(frames);
    setIsExtractingFrames(false);
    URL.revokeObjectURL(video.src);
  };

  extractFrames().catch((err) => {
    console.error("Erro ao extrair frames da película:", err);
    setIsExtractingFrames(false);
  });
}, [videoFile]);

