const groupWordsIntoPhrases = (
  wordList: { word: string; start: number; end: number }[]
) => {
  const groups: { start: number; end: number; words: typeof wordList }[] = [];
  let currentGroup: typeof wordList = [];
  const maxWords = 4;
  const maxCharLen = 28;

  wordList.forEach((w) => {
    const currentText = currentGroup.map((gw) => gw.word).join(" ");
    if (
      currentGroup.length >= maxWords ||
      (currentText + " " + w.word).length > maxCharLen
    ) {
      if (currentGroup.length > 0) {
        groups.push({
          start: currentGroup[0].start,
          end: currentGroup[currentGroup.length - 1].end,
          words: currentGroup,
        });
      }
      currentGroup = [w];
    } else {
      currentGroup.push(w);
    }
  });

  if (currentGroup.length > 0) {
    groups.push({
      start: currentGroup[0].start,
      end: currentGroup[currentGroup.length - 1].end,
      words: currentGroup,
    });
  }

  return groups;
};

const renderSubtitleFrameBlob = (
  wordsInBlock: { word: string; start: number; end: number }[],
  activeIndex: number,
  fontSize: number,
  baseColor: string,
  highlightColor: string,
  outlineColor: string,
  style: "capcut" | "neon" | "minimal",
  animation: "pop" | "none",
  mode: "phrase" | "word"
): Promise<Blob> => {
  return new Promise((resolve, reject) => {
    const canvas = document.createElement("canvas");
    canvas.width = 1920;
    canvas.height = 1080;
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      reject(new Error("Contexto Canvas 2D indisponível."));
      return;
    }
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const centerY = canvas.height * 0.78;
    const centerX = canvas.width / 2;

    let fontName = "Inter, system-ui, -apple-system, BlinkMacSystemFont, sans-serif";
    if (style === "capcut") fontName = "Impact, Arial Black, sans-serif";

    const renderWords = mode === "word" ? [wordsInBlock[activeIndex]] : wordsInBlock;
    const activeIdxInRender = mode === "word" ? 0 : activeIndex;

    if (style === "minimal") {
      ctx.font = `bold ${fontSize * 2}px ${fontName}`;
      const totalText = renderWords.map(w => w.word).join(" ");
      const textWidth = ctx.measureText(totalText).width;
      ctx.fillStyle = "rgba(0, 0, 0, 0.65)";
      const boxW = textWidth + 60;
      const boxH = fontSize * 3.0;
      ctx.beginPath();
      ctx.roundRect(centerX - boxW / 2, centerY - boxH / 2, boxW, boxH, 16);
      ctx.fill();
    }

    ctx.font = `bold ${fontSize * 2}px ${fontName}`;

    let totalWidth = 0;
    const wordWidths = renderWords.map((w, idx) => {
      let sizeMultiplier = 1.0;
      if (animation === "pop" && idx === activeIdxInRender) {
        sizeMultiplier = 1.25;
      }
      ctx.font = `bold ${fontSize * 2 * sizeMultiplier}px ${fontName}`;
      return ctx.measureText(w.word + " ").width;
    });

    totalWidth = wordWidths.reduce((a, b) => a + b, 0);
    let currentX = centerX - totalWidth / 2;

    renderWords.forEach((w, idx) => {
      let sizeMultiplier = 1.0;
      const isActive = idx === activeIdxInRender;
      if (animation === "pop" && isActive) {
        sizeMultiplier = 1.25;
      }

      ctx.font = `bold ${fontSize * 2 * sizeMultiplier}px ${fontName}`;
      ctx.fillStyle = isActive ? highlightColor : baseColor;
      ctx.textAlign = "left";
      ctx.textBaseline = "middle";

      if (style === "capcut" || style === "neon") {
        ctx.strokeStyle = outlineColor;
        ctx.lineWidth = fontSize * 0.45 * sizeMultiplier;
        ctx.lineJoin = "round";
        ctx.strokeText(w.word, currentX, centerY);
      }

      if (style === "neon" && isActive) {
        ctx.shadowColor = highlightColor;
        ctx.shadowBlur = 24;
      } else {
        ctx.shadowColor = "rgba(0, 0, 0, 0.5)";
        ctx.shadowBlur = 10;
      }

      ctx.fillText(w.word, currentX, centerY);
      ctx.shadowBlur = 0;

      currentX += wordWidths[idx];
    });

    canvas.toBlob((blob) => {
      if (blob) resolve(blob);
      else reject(new Error("Falha ao exportar frame"));
    }, "image/png");
  });
};

const handleApplyAnimatedSubtitles = async () => {
  if (!videoFile || words.length === 0) return;
  setIsGeneratingSubtitles(true);
  setCutProgress(0);
  setError(null);

  try {
    const ffmpeg = await initFFmpeg((progress) => setCutProgress(progress));
    await ffmpeg.writeFile("input.mp4", await fetchFile(videoFile));

    const blocks = subtitleMode === "word"
      ? words.map((w) => ({ start: w.start, end: w.end, words: [w] }))
      : groupWordsIntoPhrases(words);

    let filterComplex = "";
    let lastOutput = "0:v";
    const inputFiles: string[] = ["input.mp4"];

    let frameCounter = 0;
    for (let blockIdx = 0; blockIdx < blocks.length; blockIdx++) {
      const block = blocks[blockIdx];

      for (let wordIdx = 0; wordIdx < block.words.length; wordIdx++) {
        const activeWord = block.words[wordIdx];

        const blob = await renderSubtitleFrameBlob(
          block.words,
          wordIdx,
          subtitleFontSize,
          primarySubtitleColor,
          highlightSubtitleColor,
          subtitleOutlineColor,
          subtitleStyle,
          subtitleAnimation,
          subtitleMode
        );

        const frameName = `sub_${frameCounter}.png`;
        const frameFile = new File([blob], frameName, { type: "image/png" });
        await ffmpeg.writeFile(frameName, await fetchFile(frameFile));
        inputFiles.push(frameName);

        const inputIdx = inputFiles.length - 1;
        const nextOutput = `vsub_${frameCounter}`;

        filterComplex += `[${lastOutput}][${inputIdx}:v]overlay=0:0:enable='between(t,${activeWord.start.toFixed(3)},${activeWord.end.toFixed(3)})'[${nextOutput}]; `;

        lastOutput = nextOutput;
        frameCounter++;
      }
    }

    const args: string[] = [];
    inputFiles.forEach((file) => {
      args.push("-i", file);
    });

    if (filterComplex) {
      filterComplex = filterComplex.trim().replace(/;$/, "");
      args.push("-filter_complex", filterComplex);
      args.push("-map", `[${lastOutput}]`);
      args.push("-map", "0:a");
    }

    args.push("-c:v", "libx264", "-preset", "ultrafast", "-c:a", "aac", "output.mp4");

    await ffmpeg.exec(args);

    const outputData = await ffmpeg.readFile("output.mp4");
    const processedFile = new File([outputData as any], videoFile.name, { type: "video/mp4" });

    if (!originalFile) {
      setOriginalFile(videoFile);
    }
    setVideoFile(processedFile);
    setWords([]);
  } catch (err: any) {
    console.error("Erro ao aplicar legendas animadas:", err);
    setError("Falha ao renderizar legendas animadas com FFmpeg.wasm.");
  } finally {
    setIsGeneratingSubtitles(false);
  }
};

const handleMixAudio = async () => {
  if (!videoFile || !bgMusicFile) return;
  setIsApplyingEffects(true);
  setCutProgress(0);
  setError(null);

  try {
    const ffmpeg = await initFFmpeg((progress) => setCutProgress(progress));
    await ffmpeg.writeFile("input.mp4", await fetchFile(videoFile));
    await ffmpeg.writeFile("music.mp3", await fetchFile(bgMusicFile));

    const volMultiplier = (bgMusicVolume / 100).toFixed(2);

    await ffmpeg.exec([
      "-i", "input.mp4",
      "-i", "music.mp3",
      "-filter_complex", `[0:a]volume=1.0[a0]; [1:a]volume=${volMultiplier}[a1]; [a0][a1]amix=inputs=2:duration=first[aout]`,
      "-map", "0:v",
      "-map", "[aout]",
      "-c:v", "copy",
      "-c:a", "aac",
      "output.mp4"
    ]);

    const outputData = await ffmpeg.readFile("output.mp4");
    const processedFile = new File([outputData as any], videoFile.name, { type: "video/mp4" });

    if (!originalFile) {
      setOriginalFile(videoFile);
    }
    setVideoFile(processedFile);
    setBgMusicFile(null);
  } catch (err: any) {
    console.error("Erro ao mixar áudio:", err);
    setError("Falha ao mesclar música de fundo.");
  } finally {
    setIsApplyingEffects(false);
  }
};

