{/* Timeline Multifaixas */}
<div className="mt-4 glass-card rounded-xl p-4 space-y-3 select-none">
  <div className="flex items-center justify-between text-xs text-[var(--text-secondary)] font-mono">
    <span className="text-[var(--primary)] font-semibold flex items-center gap-1">
      <Film className="w-3.5 h-3.5" /> Timeline Multifaixas
    </span>
    <span>{currentTime.toFixed(2)}s / {videoDuration.toFixed(2)}s</span>
  </div>

  {videoFile ? (
    <div className="space-y-2.5 bg-[#121218] border border-[var(--border)] rounded-xl p-3 relative overflow-hidden">

      {/* Cursor de Tempo (Seek Bar Line Indicator) */}
      {videoDuration > 0 && (
        <div 
          className="absolute top-0 bottom-0 w-0.5 bg-red-500 shadow-lg shadow-red-500/50 z-10 pointer-events-none transition-all duration-75"
          style={{ left: `${(currentTime / videoDuration) * 100}%` }}
        />
      )}

      {/* Track 1: Película de Vídeo / Cortes */}
      <div 
        className="relative h-12 bg-black/40 border border-white/5 rounded-lg overflow-hidden flex cursor-pointer group"
        onClick={(e) => {
          const rect = e.currentTarget.getBoundingClientRect();
          const x = e.clientX - rect.left;
          const pct = x / rect.width;
          if (videoRef.current) {
            videoRef.current.currentTime = pct * videoDuration;
          }
        }}
      >
        {isExtractingFrames ? (
          <div className="absolute inset-0 flex items-center justify-center bg-black/60 z-10">
            <Loader2 className="w-4 h-4 animate-spin text-[var(--primary)] mr-1.5" />
            <span className="text-[10px] text-white">Extraindo frames...</span>
          </div>
        ) : timelineFrames.length > 0 ? (
          <div className="absolute inset-0 flex w-full h-full opacity-60">
            {timelineFrames.map((frame, idx) => (
              <img 
                key={idx}
                src={frame} 
                alt={`frame-${idx}`} 
                className="flex-1 h-full object-cover select-none pointer-events-none"
              />
            ))}
          </div>
        ) : (
          <div className="absolute inset-0 flex items-center justify-center">
            <span className="text-[10px] text-[var(--text-secondary)]">Película indisponível</span>
          </div>
        )}

        {/* Silêncios Detectados (Overlay Vermelho) */}
        {analysisResult && (
          <div className="absolute inset-0 w-full h-full pointer-events-none">
            {analysisResult.silences.map((sil, idx) => {
              const left = (sil.start / videoDuration) * 100;
              const width = (sil.duration / videoDuration) * 100;
              return (
                <div 
                  key={`sil-${idx}`}
                  className="absolute top-0 bottom-0 bg-red-600/40 border-x border-red-500/50"
                  style={{ left: `${left}%`, width: `${width}%` }}
                  title="Silêncio cortado"
                />
              );
            })}
          </div>
        )}
      </div>

      {/* Track 2: Faixa de Legendas */}
      <div className="relative h-8 bg-black/30 border border-white/5 rounded-lg overflow-hidden">
        <span className="absolute left-2 top-1 text-[9px] font-mono text-[var(--text-secondary)] uppercase">💬 Legendas</span>
        <div className="absolute inset-0">
          {words.length > 0 ? (
            words.map((w, idx) => {
              const left = (w.start / videoDuration) * 100;
              const width = ((w.end - w.start) / videoDuration) * 100;
              const isActive = currentTime >= w.start && currentTime <= w.end;
              return (
                <div 
                  key={`word-${idx}`}
                  className={`absolute top-3.5 bottom-1 rounded border text-[8px] flex items-center justify-center font-medium overflow-hidden truncate px-0.5 ${
                    isActive 
                      ? "bg-[var(--accent-orange)]/30 border-[var(--accent-orange)] text-white" 
                      : "bg-white/5 border-white/10 text-white/70"
                  }`}
                  style={{ left: `${left}%`, width: `${Math.max(1.5, width)}%` }}
                  title={w.word}
                >
                  {w.word}
                </div>
              );
            })
          ) : transcriptionSegments.length > 0 ? (
            transcriptionSegments.map((seg, idx) => {
              const left = (seg.start / videoDuration) * 100;
              const width = ((seg.end - seg.start) / videoDuration) * 100;
              return (
                <div 
                  key={`seg-${idx}`}
                  className={`absolute top-3.5 bottom-1 rounded border text-[8px] flex items-center justify-center font-medium overflow-hidden truncate px-0.5 ${
                    seg.enabled 
                      ? "bg-[var(--primary)]/20 border-[var(--primary)]/40 text-white" 
                      : "bg-red-500/10 border-red-500/20 text-white/40 line-through"
                  }`}
                  style={{ left: `${left}%`, width: `${width}%` }}
                  title={seg.text}
                >
                  {seg.text}
                </div>
              );
            })
          ) : (
            <div className="w-full h-full flex items-center justify-center">
              <span className="text-[9px] text-[var(--text-secondary)]">Nenhuma legenda gerada</span>
            </div>
          )}
        </div>
      </div>

      {/* Track 3: Faixa de Música de Fundo */}
      <div className="relative h-8 bg-black/30 border border-white/5 rounded-lg overflow-hidden">
        <span className="absolute left-2 top-1 text-[9px] font-mono text-[var(--text-secondary)] uppercase">🎵 Trilha Sonora</span>
        {bgMusicFile ? (
          <div className="absolute inset-x-0 top-3.5 bottom-1 mx-1 rounded border bg-[var(--accent-cyan)]/20 border-[var(--accent-cyan)]/50 text-[9px] text-white flex items-center justify-between px-2 font-medium">
            <span className="truncate flex items-center gap-1"><Music className="w-3 h-3 text-[var(--accent-cyan)]" /> {bgMusicFile.name}</span>
            <span className="text-[8px] font-mono">Vol: {bgMusicVolume}%</span>
