{/* Traditional Mode */}
{editorMode === "traditional" && (
  <div className="flex-1 flex flex-col min-h-0 bg-[#09090d] text-white">

    {/* Main workspace (Library + Monitor + Inspector) */}
    <div className="flex-1 flex min-h-0">

      {/* Left Toolbar (Vertical Icons) */}
      <div className="w-16 bg-[#101016] border-r border-[#1c1c24] flex flex-col items-center py-4 gap-5 flex-shrink-0">
        {[
          { id: "cuts", icon: Scissors, label: "Cortes" },
          { id: "subtitles", icon: Type, label: "Legendas" },
          { id: "colors", icon: Wand2, label: "Cores" },
          { id: "audio", icon: Music, label: "Áudio" },
          { id: "speed", icon: Clock, label: "Velocidade" },
          { id: "overlays", icon: LayersIcon, label: "Overlays" },
        ].map((tool) => (
          <button
            key={tool.id}
            onClick={() => setActiveToolTab(tool.id as any)}
            className={`w-12 h-12 rounded-xl flex flex-col items-center justify-center transition-all group relative ${
              activeToolTab === tool.id
                ? "bg-[var(--primary)] text-white shadow-lg shadow-[var(--primary)]/20"
                : "text-[var(--text-secondary)] hover:text-white hover:bg-[#1c1c24]"
            }`}
            title={tool.label}
          >
            <tool.icon className="w-5 h-5" />
            <span className="text-[8px] mt-1 font-medium">{tool.label}</span>
            {activeToolTab === tool.id && (
              <div className="absolute left-0 top-3 bottom-3 w-1 bg-white rounded-r" />
            )}
          </button>
        ))}
      </div>

      {/* Second Sidebar: Media Library & Asset Pool */}
      <div className="w-64 bg-[#14141c] border-r border-[#1c1c24] flex flex-col flex-shrink-0 min-h-0">
        <div className="p-4 border-b border-[#1c1c24] flex items-center justify-between">
          <h3 className="text-xs font-bold uppercase tracking-wider text-[var(--text-secondary)]">
            Mídias do Projeto
          </h3>
        </div>

        <div className="flex-1 p-3 overflow-y-auto space-y-4">
          {/* Upload Box */}
          <div
            className={`border border-dashed rounded-xl p-4 text-center cursor-pointer transition-all ${
              isDragOver
                ? "border-[var(--primary)] bg-[var(--primary)]/5"
                : "border-[#2d2d3d] hover:border-[var(--primary)] bg-[#1a1a24]/50"
            }`}
            onDragOver={(e) => {
              e.preventDefault();
              setIsDragOver(true);
            }}
            onDragLeave={() => setIsDragOver(false)}
            onDrop={(e) => {
              e.preventDefault();
              setIsDragOver(false);
              const file = e.dataTransfer.files[0];
              if (file && file.type.startsWith("video/")) {
                setVideoFile(file);
              }
            }}
          >
            <label className="cursor-pointer block">
              <Upload className="w-8 h-8 text-[var(--text-secondary)] mx-auto mb-2" />
              <span className="text-xs font-semibold text-white block">Adicionar Mídia</span>
              <span className="text-[10px] text-[var(--text-secondary)] mt-0.5 block">Arraste ou clique para selecionar</span>
              <input
                type="file"
                accept="video/*"
                onChange={(e) => {
                  const file = e.target.files?.[0];
                  if (file) setVideoFile(file);
                }}
                className="hidden"
              />
            </label>
          </div>

          {/* Active Assets list */}
          <div className="space-y-2">
            <span className="text-[10px] text-[var(--text-secondary)] font-bold uppercase block tracking-wider">
              Linha do Tempo / Arquivos
            </span>

            {videoFile ? (
              <div className="bg-[#1b1b26] border border-[#2d2d3d] rounded-lg p-2.5 relative group overflow-hidden animate-fade-in">
                <div className="flex items-start gap-2.5">
                  <div className="w-10 h-10 rounded bg-[var(--primary)]/10 flex items-center justify-center flex-shrink-0 text-[var(--primary)]">
                    <Film className="w-5 h-5" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="text-xs font-semibold text-white truncate leading-tight" title={videoFile.name}>
                      {videoFile.name}
                    </p>
                    <span className="text-[9px] text-[var(--text-secondary)] block mt-0.5 font-mono">
                      {(videoFile.size / 1024 / 1024).toFixed(1)} MB • Vídeo
                    </span>
                  </div>
                </div>
              </div>
            ) : (
              <div className="text-center py-8 text-[var(--text-secondary)] text-xs">
                Nenhum vídeo carregado.
              </div>
            )}

            {bgMusicFile && (
              <div className="bg-[#1b1b26] border border-[#2d2d3d] rounded-lg p-2.5 relative group overflow-hidden animate-fade-in">
                <div className="flex items-start gap-2.5">
                  <div className="w-10 h-10 rounded bg-[#06b6d4]/10 flex items-center justify-center flex-shrink-0 text-[#06b6d4]">
                    <Music className="w-5 h-5" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="text-xs font-semibold text-white truncate leading-tight" title={bgMusicFile.name}>
                      {bgMusicFile.name}
                    </p>
                    <span className="text-[9px] text-[var(--text-secondary)] block mt-0.5 font-mono">
                      {(bgMusicFile.size / 1024 / 1024).toFixed(1)} MB • Áudio
                    </span>
                  </div>
                </div>
              </div>
            )}

            {logoFile && (
              <div className="bg-[#1b1b26] border border-[#2d2d3d] rounded-lg p-2.5 relative group overflow-hidden animate-fade-in">
                <div className="flex items-start gap-2.5">
                  <div className="w-10 h-10 rounded bg-pink-500/10 flex items-center justify-center flex-shrink-0 text-pink-400">
                    <Image className="w-5 h-5" />
                  </div>
                  <div className="min-w-0 flex-1">
                    <p className="text-xs font-semibold text-white truncate leading-tight" title={logoFile.name}>
                      {logoFile.name}
                    </p>
                    <span className="text-[9px] text-[var(--text-secondary)] block mt-0.5 font-mono">
                      Logo Watermark
                    </span>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Center Panel - Video Preview Monitor */}
      <div className="flex-1 flex flex-col p-6 bg-[#0a0a0f] min-w-0 relative">
        <div className="flex-1 flex flex-col justify-center items-center">
          {videoFile && videoUrl ? (
            <div className="w-full max-w-4xl aspect-video rounded-2xl overflow-hidden border border-[#1f1f2b] shadow-2xl relative bg-black flex items-center justify-center group">
              <video
                ref={videoRef}
                src={videoUrl}
                className="w-full h-full object-contain"
                onTimeUpdate={handleTimeUpdate}
                onLoadedMetadata={handleLoadedMetadata}
                onEnded={() => setIsPlaying(false)}
                onClick={() => setIsPlaying(!isPlaying)}
              />
              {/* Floating Info Overlay */}
              <div className="absolute top-4 left-4 bg-black/60 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/10 text-xs font-medium text-white shadow-lg animate-fade-in">
                {videoFile.name}
              </div>
            </div>
          ) : (
            <div className="w-full max-w-md aspect-video border-2 border-dashed border-[#2d2d3d] hover:border-[var(--primary)] rounded-2xl flex flex-col items-center justify-center p-6 text-center transition-all bg-[#14141c]/40">
              <div className="w-16 h-16 rounded-full bg-gradient-to-br from-[var(--primary)]/10 to-[var(--accent-pink)]/10 flex items-center justify-center mb-4">
                <Film className="w-8 h-8 text-[var(--primary)]" />
              </div>
              <p className="text-sm font-semibold text-white mb-1">Escolha um vídeo para começar</p>
              <p className="text-xs text-[var(--text-secondary)] mb-4 max-w-[280px]">Arraste o arquivo ou use o painel da esquerda para importar mídias.</p>
            </div>
          )}
        </div>

        {/* Monitor Controls Bar */}
        {videoFile && (
          <div className="mt-4 max-w-4xl w-full mx-auto bg-[#14141c]/80 backdrop-blur-md border border-[#1f1f2b] rounded-2xl p-4 flex flex-col gap-3 shadow-xl">
            <div className="flex items-center justify-between gap-4">
              <div className="flex items-center gap-3">
                <button
                  onClick={() => {
                    if (videoRef.current) {
                      videoRef.current.currentTime = Math.max(0, currentTime - 5);
                    }
                  }}
                  className="p-2 hover:bg-[#22222f] rounded-lg transition-colors text-[var(--text-secondary)] hover:text-white"
                  title="Voltar 5s"
                >
                  <SkipBack className="w-4 h-4" />
                </button>
                <button
                  onClick={() => setIsPlaying(!isPlaying)}
                  className="p-3 bg-[var(--primary)] rounded-full hover:bg-[var(--primary-hover)] text-white shadow-md shadow-[var(--primary)]/20 transition-all hover:scale-105"
                  title={isPlaying ? "Pausar" : "Reproduzir"}
                >
                  {isPlaying ? <Pause className="w-5 h-5" /> : <Play className="w-5 h-5 ml-0.5" />}
                </button>
                <button
                  onClick={() => {
                    if (videoRef.current) {
                      videoRef.current.currentTime = Math.min(videoDuration, currentTime + 5);
                    }
                  }}
                  className="p-2 hover:bg-[#22222f] rounded-lg transition-colors text-[var(--text-secondary)] hover:text-white"
                  title="Avançar 5s"
                >
                  <SkipForward className="w-4 h-4" />
                </button>
              </div>

              <div className="text-sm font-mono font-bold tracking-wider text-white">
                {formatTime(currentTime)} <span className="text-[var(--text-secondary)]">/</span> {formatTime(videoDuration)}
              </div>

              <div className="flex items-center gap-3">
                <button
                  onClick={() => setIsMuted(!isMuted)}
                  className="p-2 hover:bg-[#22222f] rounded-lg transition-colors text-[var(--text-secondary)] hover:text-white"
                >
                  {isMuted ? <VolumeX className="w-4 h-4 text-red-400" /> : <Volume2 className="w-4 h-4" />}
                </button>
                <input
                  type="range"
                  min="0"
                  max="100"
                  value={isMuted ? 0 : volume}
                  onChange={(e) => setVolume(Number(e.target.value))}
                  className="w-20 h-1 accent-[var(--primary)] bg-[#2a2a3a] rounded-lg cursor-pointer appearance-none"
                />
              </div>
            </div>
          </div>
