            {/* Silence Red Marks Overlay */}
            {analysisResult && (
              <div className="absolute inset-0 w-full h-full pointer-events-none z-10">
                {analysisResult.silences.map((silence, idx) => {
                  const leftPct = (silence.start / videoDuration) * 100;
                  const widthPct = (silence.duration / videoDuration) * 100;
                  return (
                    <div
                      key={idx}
                      className="absolute h-full bg-red-600/35 border-x border-red-600/50 flex items-center justify-center"
                      style={{ left: `${leftPct}%`, width: `${widthPct}%` }}
