              </div>
            )}
          </div>

          {/* Track 2: Subtitle Words tag lane */}
          <div className="relative h-7 bg-black/30 border border-white/5 rounded-lg overflow-hidden flex items-center">
            <span className="absolute left-2 text-[8px] text-[var(--text-secondary)] font-bold uppercase z-10">T1 Legendas</span>
            {words.length > 0 && videoDuration > 0 ? (
              <div className="absolute inset-0 w-full h-full pointer-events-none">
                {words.map((w, idx) => {
                  const leftPct = (w.start / videoDuration) * 100;
                  const widthPct = ((w.end - w.start) / videoDuration) * 100;
                  const isActive = currentTime >= w.start && currentTime <= w.end;
                  return (
                    <div
                      key={idx}
                      className={`absolute h-full border-r border-white/5 flex items-center justify-center px-0.5 text-[8px] font-semibold truncate transition-colors ${
