              </div>
            ) : (
              <div className="absolute inset-0 flex items-center justify-center">
                <span className="text-[9px] text-[var(--text-secondary)]">Legendas IA inactivas</span>
              </div>
            )}
          </div>

          {/* Track 3: Audio Background Track */}
          <div className="relative h-7 bg-black/30 border border-white/5 rounded-lg overflow-hidden flex items-center">
            <span className="absolute left-2 text-[8px] text-[var(--text-secondary)] font-bold uppercase z-10">A1 Trilha</span>
            {bgMusicFile && videoDuration > 0 ? (
              <div
                className="absolute inset-y-0 bg-[#06b6d4]/15 border-y border-[#06b6d4]/30 rounded flex items-center px-3 gap-1.5 transition-all text-[9px] text-[#06b6d4] font-semibold"
