                <span className="truncate">{bgMusicFile.name} (Volume {bgMusicVolume}%)</span>
              </div>
            ) : (
              <div className="absolute inset-0 flex items-center justify-center">
                <span className="text-[9px] text-[var(--text-secondary)]">Sem música de fundo</span>
              </div>
            )}
          </div>
        </div>
      </div>
    )}
  </div>
)}

args.TargetContent:
