const fs = require('fs');
const readline = require('readline');

const originalCode = fs.readFileSync('src/app/editor/page.tsx', 'utf8');

const fileStream = fs.createReadStream('logs_temp.jsonl');
const rl = readline.createInterface({
  input: fileStream,
  crlfDelay: Infinity
});

const edits = [];

rl.on('line', (line) => {
  try {
    const data = JSON.parse(line);
    // Only apply edits from previous sessions (step_index < 1060)
    if (data.step_index >= 1060) return;

    const toolCalls = data.tool_calls || [];
    for (const tc of toolCalls) {
      if (tc.name === 'replace_file_content' && tc.args && tc.args.TargetFile && tc.args.TargetFile.includes('editor/page.tsx')) {
        edits.push({
          step: data.step_index,
          target: tc.args.TargetContent,
          replacement: tc.args.ReplacementContent
        });
      }
    }
  } catch (e) {
    // ignore
  }
});

rl.on('close', () => {
  console.log(`Found ${edits.length} edits to apply.`);
  let code = originalCode;

  for (const edit of edits) {
    console.log(`Applying edit from step ${edit.step}...`);
    const index = code.indexOf(edit.target);
    if (index === -1) {
      console.error(`ERROR: Target content not found for step ${edit.step}!`);
      // Print first 50 chars of target
      console.log("Target start:", edit.target.slice(0, 80));
      continue;
    }

    // Replace only the first occurrence to match replace_file_content behavior
    code = code.substring(0, index) + edit.replacement + code.substring(index + edit.target.length);
  }

  fs.writeFileSync('src/app/editor/page.tsx', code);
  console.log("Successfully reconstructed src/app/editor/page.tsx!");
});

