        // Clean up double-escaped quotes and normalize whitespace/newlines if needed
        let target = tc.args.TargetContent;
        let replacement = tc.args.ReplacementContent;

        // Normalize CRLF to LF to avoid carriage return mismatches
        target = target.replace(/\r\n/g, '\n');
