function normalize(str) {
  if (!str) return '';
  let res = str.replace(/\r\n/g, '\n');
  // Strip outer quotes if they exist literally
  if (res.startsWith('"') && res.endsWith('"')) {
    res = res.slice(1, -1);
  }
  // Replace escaped quotes
  res = res.replace(/\\"/g, '"');
  // Replace double-escaped newlines
  res = res.replace(/\\n/g, '\n');
  res = res.replace(/\\t/g, '\t');
  res = res.replace(/\\\\/g, '\\');
  return res;
}

rl.on('line', (line) => {
  try {
    const data = JSON.parse(line);
    if (data.step_index >= 1060) return;

    const toolCalls = data.tool_calls || [];
